  final String fakeAndroidId;
  final String huaweiAddress;
  final PlatformInt64? lastSyncMs;
  final bool migrated;

  /// 自托管星历 zip 地址；空表示不主动补星历（手表只能自己搜星冷启动）
  final String ephemerisUrl;

  const WatchIdentity({
    required this.address,
    required this.name,
    required this.account,
    required this.authKey,
    required this.fakeAndroidId,
    required this.huaweiAddress,
    this.lastSyncMs,
    required this.migrated,
    required this.ephemerisUrl,
  });

  @override
  int get hashCode =>
      address.hashCode ^
      name.hashCode ^
      account.hashCode ^
      authKey.hashCode ^
      fakeAndroidId.hashCode ^
      huaweiAddress.hashCode ^
      lastSyncMs.hashCode ^
      migrated.hashCode ^
      ephemerisUrl.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WatchIdentity &&
          runtimeType == other.runtimeType &&
          address == other.address &&
          name == other.name &&
          account == other.account &&
          authKey == other.authKey &&
          fakeAndroidId == other.fakeAndroidId &&
          huaweiAddress == other.huaweiAddress &&
          lastSyncMs == other.lastSyncMs &&
          migrated == other.migrated &&
          ephemerisUrl == other.ephemerisUrl;
}

/// 手表连接与同步日志的一行，由原生层抛出、watch.rs 落库。
class WatchLog {
  final PlatformInt64 tsMs;
  final String msg;

  const WatchLog({required this.tsMs, required this.msg});

  @override
  int get hashCode => tsMs.hashCode ^ msg.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WatchLog &&
          runtimeType == other.runtimeType &&
          tsMs == other.tsMs &&
          msg == other.msg;
}

