class WorkoutDetail {
  final WorkoutSummary summary;
  final double aerobicEffect;
  final double anaerobicEffect;
  final PlatformInt64 recoveryTimeMin;
  final double? maxMet;
  final double? vo2Max;
  final double? elevationGain;
  final double? elevationLoss;
  final double? avgPaceSec;
  final double? cadence;
  final String? trackJson;
  final String? samplesJson;
  final String? dynamicsJson;
  final String? altitudeJson;
  final String? recoveryJson;

  /// 手表官方分段（0x0c）：type=0 为整公里，type=1 为整英里。
  final String? splitsJson;

  /// 游泳分段（WorkoutSwimSegments）：泳池每段的距离、配速、划水次数与 SWOLF。
  final String? swimSegmentsJson;
  final double? startTempC;
  final PlatformInt64? startHumidity;

  /// 手表 tag 0x63：训练积分。
  final PlatformInt64? trainingPoints;

  /// 手表 tag 0x0f：EPOC 原始值。
  final PlatformInt64? epoc;

  /// 手表 0xe7 扩展统计：字段编号 → 原始字符串值的 JSON 对象。
  final String? statExtendJson;

  /// 手表 0x50–0x5a：跑步配速区间，原始秒/公里与各区间秒数。
  final String? runPaceZonesJson;
  final double? maxAltitude;
  final double? minAltitude;
  final PlatformInt64? algType;
  final PlatformInt64 uploadStatus;

  const WorkoutDetail({
    required this.summary,
    required this.aerobicEffect,
    required this.anaerobicEffect,
    required this.recoveryTimeMin,
    this.maxMet,
    this.vo2Max,
    this.elevationGain,
    this.elevationLoss,
    this.avgPaceSec,
    this.cadence,
    this.trackJson,
    this.samplesJson,
    this.dynamicsJson,
    this.altitudeJson,
    this.recoveryJson,
    this.splitsJson,
    this.swimSegmentsJson,
    this.startTempC,
    this.startHumidity,
    this.trainingPoints,
    this.epoc,
    this.statExtendJson,
    this.runPaceZonesJson,
    this.maxAltitude,
    this.minAltitude,
    this.algType,
    required this.uploadStatus,
  });

  @override
  int get hashCode =>
      summary.hashCode ^
      aerobicEffect.hashCode ^
      anaerobicEffect.hashCode ^
      recoveryTimeMin.hashCode ^
      maxMet.hashCode ^
      vo2Max.hashCode ^
      elevationGain.hashCode ^
      elevationLoss.hashCode ^
      avgPaceSec.hashCode ^
      cadence.hashCode ^
      trackJson.hashCode ^
      samplesJson.hashCode ^
      dynamicsJson.hashCode ^
      altitudeJson.hashCode ^
      recoveryJson.hashCode ^
      splitsJson.hashCode ^
      swimSegmentsJson.hashCode ^
      startTempC.hashCode ^
      startHumidity.hashCode ^
      trainingPoints.hashCode ^
      epoc.hashCode ^
      statExtendJson.hashCode ^
      runPaceZonesJson.hashCode ^
      maxAltitude.hashCode ^
      minAltitude.hashCode ^
      algType.hashCode ^
      uploadStatus.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WorkoutDetail &&
          runtimeType == other.runtimeType &&
          summary == other.summary &&
          aerobicEffect == other.aerobicEffect &&
          anaerobicEffect == other.anaerobicEffect &&
          recoveryTimeMin == other.recoveryTimeMin &&
          maxMet == other.maxMet &&
          vo2Max == other.vo2Max &&
          elevationGain == other.elevationGain &&
          elevationLoss == other.elevationLoss &&
          avgPaceSec == other.avgPaceSec &&
          cadence == other.cadence &&
          trackJson == other.trackJson &&
          samplesJson == other.samplesJson &&
          dynamicsJson == other.dynamicsJson &&
          altitudeJson == other.altitudeJson &&
          recoveryJson == other.recoveryJson &&
          splitsJson == other.splitsJson &&
          swimSegmentsJson == other.swimSegmentsJson &&
          startTempC == other.startTempC &&
          startHumidity == other.startHumidity &&
          trainingPoints == other.trainingPoints &&
          epoc == other.epoc &&
          statExtendJson == other.statExtendJson &&
          runPaceZonesJson == other.runPaceZonesJson &&
