      other is WorkoutWeatherCandidate &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          startMs == other.startMs &&
          lat == other.lat &&
          lon == other.lon &&
          startTempC == other.startTempC &&
          startHumidity == other.startHumidity;
}
